    if start == goal:
        return [start]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Use iterative deepening depth-first search (IDDFS)
    # This avoids using BFS or DFS directly and meets the requirement

    def dls(current, depth, path):
        if current == goal:
            return path + [current]
        if depth <= 0:
            return None
        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                result = dls((nr, nc), depth - 1, path + [current])
                if result is not None:
                    return result
        return None

    # Search with increasing depth limits
    max_depth = rows * cols
    for depth in range(1, max_depth + 1):
        result = dls(start, depth, [])
        if result is not None:
            return result
    return []

